import test from 'node:test';import assert from 'node:assert/strict';import {createCommerceQueries} from '../src/lib/commerceQueries.js';
test('missing request id never invokes backend',async()=>{let n=0;const q=createCommerceQueries(async()=>n++);await assert.rejects(q.createEstablishment({type:'boutique',data:{pays_code:'BF'}}),/REQUEST_ID/);assert.equal(n,0)});
test('explicit recovery keeps caller request ID without generated replacement',async()=>{const requests=[];const q=createCommerceQueries(async(name,body)=>{requests.push(body);return {success:true,record:{id:'shop',pays_code:'BF'}}});const req={type:'boutique',data:{nom:'Shop',pays_code:'BF'},requestId:'stable'};await q.createEstablishment(req);await q.createEstablishment(req);assert.equal(requests.length,2);assert.equal(requests[0].request_id,'stable');assert.equal(requests[1].request_id,'stable')});
test('creation uncertainty never triggers retry',async()=>{let n=0;const q=createCommerceQueries(async()=>{n++;throw Error('lost')});await assert.rejects(q.createProduct({type:'boutique',establishmentId:'shop',data:{},requestId:'stable'}));assert.equal(n,1)});
test('product creation rejects receipt from wrong parent',async()=>{const q=createCommerceQueries(async()=>({success:true,record:{id:'p',boutique_id:'other'}}));await assert.rejects(q.createProduct({type:'boutique',establishmentId:'shop',data:{},requestId:'stable'}),e=>e.uncertain===true)});
test('establishment creation rejects receipt from wrong country',async()=>{const q=createCommerceQueries(async()=>({success:true,record:{id:'shop',pays_code:'CI'}}));await assert.rejects(q.createEstablishment({type:'boutique',data:{pays_code:'BF'},requestId:'stable'}),e=>e.uncertain===true)});
test('restaurant product receipt checks restaurant relation',async()=>{const q=createCommerceQueries(async()=>({success:true,record:{id:'p',restaurant_id:'r'}}));const r=await q.createProduct({type:'restaurant',establishmentId:'r',data:{},requestId:'stable'});assert.equal(r.record.id,'p')});
